import {test} from 'node:test';import assert from 'node:assert/strict';import {httpEnvironment} from './support.js';
async function drafts(s){const source=await s.ok('/api/guidelines?filename=placeholder.pdf&document_id=PLACEHOLDER-CHECKS',s.bytes);await s.ok(`/api/guidelines/${source.sha256}/metadata`,{edition:'placeholder'});await s.ok(`/api/guidelines/${source.sha256}/digitise`,{});const sample=await s.ok('/api/sample-bundle'),blocks=await s.ok(`/api/guidelines/${source.sha256}/blocks`);sample.atc_by_block=Object.fromEntries(Object.entries(sample.atc_by_block).filter(([id])=>blocks.some(b=>b.id===id)));return {source,...await s.ok(`/api/guidelines/${source.sha256}/draft`,{atc_by_block:sample.atc_by_block})};}
test('sample clinical review and release need no manual test loading or saving',async t=>{const s=await httpEnvironment(t,{shipped:true}),d=await drafts(s);assert.equal(d.nodes.length,4);for(const entry of d.nodes){const path='/api/ir/'+entry.node.id;assert.equal((await s.ok(path+'/checks',{})).status,'passed');for(const reviewer of ['PLACEHOLDER A','PLACEHOLDER B'])await s.ok(path+'/approve',{reviewer});}const release=await s.ok('/api/releases',{document_sha256:d.source.sha256,version:'poc-demo-0.8.0'});assert.ok(release.fixture_count>0);const entry=d.nodes.find(e=>e.node.type==='table'),before=await s.ok('/api/fixtures?node='+entry.node.id);await s.ok('/api/ir/'+entry.node.id+'/edit',{message_template:'PLACEHOLDER changed {value}'});const checks=await s.ok('/api/ir/'+entry.node.id+'/checks',{});assert.equal(checks.status,'needs_attention');assert.match(checks.message,/rule has changed/);const after=await s.ok('/api/fixtures?node='+entry.node.id);assert.equal(after.stale,true);assert.equal(after.content_hash,before.content_hash);for(const reviewer of ['PLACEHOLDER A','PLACEHOLDER B'])await s.ok('/api/ir/'+entry.node.id+'/approve',{reviewer});assert.equal((await s.request('/api/releases',{document_sha256:d.source.sha256,version:'poc-demo-0.8.1'})).status,409);});
test('non-sample rules still require engineering checks and failures are not auto-approved',async t=>{const s=await httpEnvironment(t),d=await drafts(s),node=d.nodes.find(e=>e.node.type==='table').node,path='/api/ir/'+node.id;const missing=await s.ok(path+'/checks',{});assert.equal(missing.status,'needs_attention');assert.match(missing.message,/not been supplied/);assert.equal((await s.ok('/api/fixtures?node='+node.id)).entries.length,0);assert.equal((await s.request(path+'/checks',{unexpected:true})).status,400);});
test('release independently attaches sample checks without loading the review summary',async t=>{const s=await httpEnvironment(t,{shipped:true}),d=await drafts(s);for(const entry of d.nodes)for(const reviewer of ['PLACEHOLDER A','PLACEHOLDER B'])await s.ok('/api/ir/'+entry.node.id+'/approve',{reviewer});assert.ok((await s.ok('/api/releases',{document_sha256:d.source.sha256,version:'poc-demo-0.8.2'})).fixture_count>0);});

test('failing authored expectations remain failures rather than being regenerated',async t=>{const s=await httpEnvironment(t,{shipped:true}),d=await drafts(s),node=d.nodes.find(e=>e.node.type==='table').node,path='/api/ir/'+node.id;assert.equal((await s.ok(path+'/checks',{})).status,'passed');const f=await s.ok('/api/fixtures?node='+node.id),entries=structuredClone(f.entries);entries[0].expect=entries[0].expect.length?[]:[node.id];await s.ok('/api/fixtures',{node_id:node.id,entries});const checks=await s.ok(path+'/checks',{});assert.equal(checks.status,'needs_attention');assert.match(checks.details.error,/Fixture mismatch/);assert.deepEqual((await s.ok('/api/fixtures?node='+node.id)).entries,entries);});
